# data.py: everything the arenas packs are made from. One entry per place: its painting, a short note, and its rows.
# A row: id, kind, what (plain words), box (x0, y0, x1, y1 in the place's full-size painting), shared (True/False),
# and, when this pack makes it: 'ref' (crop box, if not the row's box), 'stand' (stand-in box) with 'sq' (squash),
# 'src' (another painting the stand-in is cut from), 'backdrop' (save the box at full width), and 'p' (the prompt).
# Rows with list=True are only listed here (another place or group makes them).
A = '/home/claude/envoi-game/reference/art/'
BB = A + 'battle-backgrounds/'
WALK = A + 'walk/'

NIGHT = 'Night, under a bright full moon: cool silver-lavender moonlight, plum-indigo shadows'

PLACES = {}

